"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_NUMBER = r"(?:0|[1-9][0-9]*)"
_IDENTIFIERS = r"[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*"
_VERSION_RE = re.compile(
    rf"({_NUMBER})\.({_NUMBER})\.({_NUMBER})"
    rf"(?:-({_IDENTIFIERS}))?(?:\+({_IDENTIFIERS}))?"
)
_DIGITS_RE = re.compile(r"[0-9]+")
_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.*)", re.DOTALL)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, prerelease, build = match.groups()
    pre = tuple(prerelease.split(".")) if prerelease is not None else ()
    for identifier in pre:
        if _DIGITS_RE.fullmatch(identifier) and identifier != str(int(identifier)):
            raise ValueError(f"invalid version: {text!r}")
    return Version(
        int(major),
        int(minor),
        int(patch),
        pre,
        tuple(build.split(".")) if build is not None else (),
    )


def _coerce(version: str | Version) -> Version:
    if isinstance(version, Version):
        return version
    return parse(version)


def _sign(x: object, y: object) -> int:
    return (x > y) - (x < y)


def _compare_identifiers(a: str, b: str) -> int:
    a_numeric = _DIGITS_RE.fullmatch(a) is not None
    b_numeric = _DIGITS_RE.fullmatch(b) is not None
    if a_numeric and b_numeric:
        return _sign(int(a), int(b))
    if a_numeric or b_numeric:
        # All-digit identifiers rank below the rest.
        return -1 if a_numeric else 1
    return _sign(a, b)


def _compare(a: Version, b: Version) -> int:
    result = _sign((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    if result:
        return result
    if not a.prerelease or not b.prerelease:
        # A version without a pre-release ranks above one with.
        return _sign(not a.prerelease, not b.prerelease)
    for x, y in zip(a.prerelease, b.prerelease):
        result = _compare_identifiers(x, y)
        if result:
            return result
    return _sign(len(a.prerelease), len(b.prerelease))


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare(_coerce(a), _coerce(b))


def _parse_comparator(text: str) -> tuple[Version, list[tuple[str, Version]]]:
    """The version as written, and the simple checks it expands to."""
    match = _COMPARATOR_RE.fullmatch(text)
    operator = match.group(1) or "="
    version = parse(match.group(2))
    if operator == "^":
        if version.major:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return version, [(">=", version), ("<", upper)]
    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return version, [(">=", version), ("<", upper)]
    return version, [(operator, version)]


def _check(version: Version, operator: str, bound: Version) -> bool:
    result = _compare(version, bound)
    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    return result <= 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _coerce(version)
    # Parse the whole range first so an invalid one always raises.
    sets = []
    for part in range_.split("||"):
        comparators = [_parse_comparator(token) for token in part.split()]
        if not comparators:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append(comparators)
    core = (version.major, version.minor, version.patch)
    for comparators in sets:
        if version.prerelease and not any(
            written.prerelease
            and (written.major, written.minor, written.patch) == core
            for written, _ in comparators
        ):
            continue
        if all(
            _check(version, operator, bound)
            for _, checks in comparators
            for operator, bound in checks
        ):
            return True
    return False

