from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_CELL = re.compile(r":?-+:?")


def _cell_text(value) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    space = width - len(text)
    if alignment == "right":
        return " " * space + text
    if alignment == "center":
        left = space // 2
        return " " * left + text + " " * (space - left)
    return text + " " * space


def _delimiter(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    count = len(header)
    if align is None:
        align = [None] * count
    else:
        align = list(align)
        if len(align) != count:
            raise ValueError(
                f"align has {len(align)} entries for {count} columns"
            )
        for alignment in align:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    head = [_cell_text(value) for value in header]
    body = []
    for row in rows:
        if len(row) > count:
            raise ValueError(
                f"row has {len(row)} cells but the header has {count}"
            )
        cells = [_cell_text(value) for value in row]
        body.append(cells + [""] * (count - len(cells)))

    widths = [
        max([3, len(head[i])] + [len(cells[i]) for cells in body])
        for i in range(count)
    ]

    lines = [
        _line([_pad(head[i], widths[i], align[i]) for i in range(count)]),
        _line([_delimiter(widths[i], align[i]) for i in range(count)]),
    ]
    for cells in body:
        lines.append(
            _line([_pad(cells[i], widths[i], align[i]) for i in range(count)])
        )
    return "\n".join(lines)


def _split_line(line: str) -> list[str]:
    """Split a table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    cells = []
    current = []
    i = 0
    while i < len(line):
        char = line[i]
        if char == "\\" and line[i + 1 : i + 2] == "|":
            current.append("|")
            i += 2
            continue
        if char == "|":
            cells.append("".join(current).strip())
            current = []
        else:
            current.append(char)
        i += 1
    cells.append("".join(current).strip())
    return cells


def _alignment(cell: str) -> str | None:
    if not _DELIMITER_CELL.fullmatch(cell):
        raise ValueError(f"invalid delimiter cell: {cell!r}")
    left = cell.startswith(":")
    right = cell.endswith(":")
    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = [line for line in text.splitlines() if line.strip()]
    if len(lines) < 2:
        raise ValueError("a table needs a header line and a delimiter line")

    header = _split_line(lines[0])
    count = len(header)
    delimiter = _split_line(lines[1])
    if len(delimiter) != count:
        raise ValueError(
            f"delimiter line has {len(delimiter)} cells "
            f"but the header has {count}"
        )
    align = [_alignment(cell) for cell in delimiter]

    rows = []
    for line in lines[2:]:
        cells = _split_line(line)
        if len(cells) != count:
            raise ValueError(
                f"row has {len(cells)} cells but the header has {count}"
            )
        rows.append(cells)
    return header, rows, align
